import{_t as e,it as t,n,rt as r}from"./chunks/framework.1B5JQyNh.js";var i=JSON.parse(`{"title":"micro509/pkcs","description":"","frontmatter":{"title":"micro509/pkcs","packageVersion":"0.1.1"},"headers":[],"relativePath":"api/pkcs.md","filePath":"site/versions/v0.1.1/api/pkcs.md","lastUpdated":0}`),a={name:`api/pkcs.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="micro509-pkcs" tabindex="-1"><code>micro509/pkcs</code> <a class="header-anchor" href="#micro509-pkcs" aria-label="Permalink to “micro509/pkcs”">​</a></h1><p>PKCS container APIs: PFX/PKCS#12 and PKCS#7/CMS.</p><p>Owns PFX archive creation and parsing, PKCS#7 certificate bags and SignedData, and PKCS#12 MAC integrity helpers.</p><h2 id="functions" tabindex="-1">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to “Functions”">​</a></h2><ul><li><span id="fn-createpfx"></span><a href="/v0.1.1/api/fn/createPfx"><code>createPfx</code></a> — Builds a PKCS#12/PFX archive containing certificates and/or private keys.</li><li><span id="fn-parsepfxder"></span><a href="/v0.1.1/api/fn/parsePfxDer"><code>parsePfxDer</code></a> — Decodes a DER-encoded PKCS#12/PFX container into its constituent bags.</li><li><span id="fn-parsepfxpem"></span><a href="/v0.1.1/api/fn/parsePfxPem"><code>parsePfxPem</code></a> — Decodes a PEM-armored PKCS#12/PFX container. Expects exactly one <code>PKCS12</code> block.</li><li><span id="fn-createpkcs7certbagder"></span><a href="/v0.1.1/api/fn/createPkcs7CertBagDer"><code>createPkcs7CertBagDer</code></a> — Creates a degenerate PKCS#7 SignedData structure containing only certificates (no signers).</li><li><span id="fn-createpkcs7certbagpem"></span><a href="/v0.1.1/api/fn/createPkcs7CertBagPem"><code>createPkcs7CertBagPem</code></a> — Creates a degenerate PKCS#7 SignedData certificate bag and returns DER, PEM, and base64 forms.</li><li><span id="fn-parsepkcs7certbagder"></span><a href="/v0.1.1/api/fn/parsePkcs7CertBagDer"><code>parsePkcs7CertBagDer</code></a> — Parses a DER-encoded PKCS#7 cert bag, returning the contained certificates.</li><li><span id="fn-parsepkcs7certbagpem"></span><a href="/v0.1.1/api/fn/parsePkcs7CertBagPem"><code>parsePkcs7CertBagPem</code></a> — Parses a PEM-armored PKCS#7 cert bag. Expects exactly one <code>PKCS7</code> PEM block.</li><li><span id="fn-parsepkcs7signeddatader"></span><a href="/v0.1.1/api/fn/parsePkcs7SignedDataDer"><code>parsePkcs7SignedDataDer</code></a> — Decodes a DER-encoded PKCS#7 ContentInfo expecting <code>signedData</code> content type.</li><li><span id="fn-parsepkcs7signeddatapem"></span><a href="/v0.1.1/api/fn/parsePkcs7SignedDataPem"><code>parsePkcs7SignedDataPem</code></a> — Decodes a PEM-armored PKCS#7 SignedData. Expects exactly one <code>PKCS7</code> PEM block.</li><li><span id="fn-verifypkcs7signeddata"></span><a href="/v0.1.1/api/fn/verifyPkcs7SignedData"><code>verifyPkcs7SignedData</code></a> — Verifies all signer signatures in a PKCS#7 SignedData structure.</li><li><span id="fn-createpkcs12macdata"></span><a href="/v0.1.1/api/fn/createPkcs12MacData"><code>createPkcs12MacData</code></a> — Computes a PKCS#12 HMAC-SHA-256 MAC over the AuthenticatedSafe and returns</li><li><span id="fn-parsepkcs12macdata"></span><a href="/v0.1.1/api/fn/parsePkcs12MacData"><code>parsePkcs12MacData</code></a> — Decodes a DER-encoded MacData block. When <code>password</code> is provided, verifies</li></ul><h2 id="types" tabindex="-1">Types <a class="header-anchor" href="#types" aria-label="Permalink to “Types”">​</a></h2><ul><li><span id="type-createpfxinput"></span><a href="/v0.1.1/api/type/CreatePfxInput"><code>CreatePfxInput</code></a> — Input for <a href="/v0.1.1/api/fn/createPfx"><code>createPfx</code></a>.</li><li><span id="type-parsedpfx"></span><a href="/v0.1.1/api/type/ParsedPfx"><code>ParsedPfx</code></a> — Fully decoded PFX container returned by <a href="/v0.1.1/api/fn/parsePfxDer"><code>parsePfxDer</code></a> / <a href="/v0.1.1/api/fn/parsePfxPem"><code>parsePfxPem</code></a>.</li><li><span id="type-parsedpfxattribute"></span><a href="/v0.1.1/api/type/ParsedPfxAttribute"><code>ParsedPfxAttribute</code></a> — A single PKCS#12 bag attribute as decoded by <a href="/v0.1.1/api/fn/parsePfxDer"><code>parsePfxDer</code></a>.</li><li><span id="type-parsedpfxbag"></span><a href="/v0.1.1/api/type/ParsedPfxBag"><code>ParsedPfxBag</code></a> — Discriminated union of SafeBag types decoded from a PFX container.</li><li><span id="type-parsedpfxbagattributes"></span><a href="/v0.1.1/api/type/ParsedPfxBagAttributes"><code>ParsedPfxBagAttributes</code></a> — Decoded bag attributes for a single SafeBag inside a PFX.</li><li><span id="type-parsepfxerrorcode"></span><a href="/v0.1.1/api/type/ParsePfxErrorCode"><code>ParsePfxErrorCode</code></a> — Error codes returned by <a href="/v0.1.1/api/fn/parsePfxDer"><code>parsePfxDer</code></a> and <a href="/v0.1.1/api/fn/parsePfxPem"><code>parsePfxPem</code></a>.</li><li><span id="type-parsepfxfailure"></span><a href="/v0.1.1/api/type/ParsePfxFailure"><code>ParsePfxFailure</code></a> — Error payload for a failed PFX parse.</li><li><span id="type-parsepfxoptions"></span><a href="/v0.1.1/api/type/ParsePfxOptions"><code>ParsePfxOptions</code></a> — Options for <a href="/v0.1.1/api/fn/parsePfxDer"><code>parsePfxDer</code></a> and <a href="/v0.1.1/api/fn/parsePfxPem"><code>parsePfxPem</code></a>.</li><li><span id="type-parsepfxresult"></span><a href="/v0.1.1/api/type/ParsePfxResult"><code>ParsePfxResult</code></a> — Success-or-failure result from <a href="/v0.1.1/api/fn/parsePfxDer"><code>parsePfxDer</code></a> / <a href="/v0.1.1/api/fn/parsePfxPem"><code>parsePfxPem</code></a>.</li><li><span id="type-pbes2encryptionoptions"></span><a href="/v0.1.1/api/type/Pbes2EncryptionOptions"><code>Pbes2EncryptionOptions</code></a> — Input for <code>encryptPbes2</code>.</li><li><span id="type-pbes2encryptionscheme"></span><a href="/v0.1.1/api/type/Pbes2EncryptionScheme"><code>Pbes2EncryptionScheme</code></a> — AES-CBC key sizes supported by this PBES2 implementation.</li><li><span id="type-pbes2prf"></span><a href="/v0.1.1/api/type/Pbes2Prf"><code>Pbes2Prf</code></a> — PBKDF2 pseudo-random function choices. <code>hmac-sha1</code> is the RFC default; <code>hmac-sha256</code> is preferred.</li><li><span id="type-pfxbagattributesinput"></span><a href="/v0.1.1/api/type/PfxBagAttributesInput"><code>PfxBagAttributesInput</code></a> — Optional metadata attached to a certificate or key bag inside a PFX.</li><li><span id="type-pfxcertificatebaginput"></span><a href="/v0.1.1/api/type/PfxCertificateBagInput"><code>PfxCertificateBagInput</code></a> — A certificate to embed in a PFX container. Input for <a href="/v0.1.1/api/fn/createPfx"><code>createPfx</code></a>.</li><li><span id="type-pfxcertificatesource"></span><a href="/v0.1.1/api/type/PfxCertificateSource"><code>PfxCertificateSource</code></a> — PEM string or DER bytes for a certificate to include in a PFX bag.</li><li><span id="type-pfxencryptionoptions"></span><a href="/v0.1.1/api/type/PfxEncryptionOptions"><code>PfxEncryptionOptions</code></a> — PBES2 encryption settings for PFX key-bag protection. Alias of <a href="/v0.1.1/api/type/Pbes2EncryptionOptions"><code>Pbes2EncryptionOptions</code></a>.</li><li><span id="type-pfxmaterial"></span><a href="/v0.1.1/api/type/PfxMaterial"><code>PfxMaterial</code></a> — DER, PEM, and base64 encodings of a PFX container produced by <a href="/v0.1.1/api/fn/createPfx"><code>createPfx</code></a>.</li><li><span id="type-pfxprivatekeybaginput"></span><a href="/v0.1.1/api/type/PfxPrivateKeyBagInput"><code>PfxPrivateKeyBagInput</code></a> — A private key to embed in a PFX container. Input for <a href="/v0.1.1/api/fn/createPfx"><code>createPfx</code></a>.</li><li><span id="type-pfxprivatekeysource"></span><a href="/v0.1.1/api/type/PfxPrivateKeySource"><code>PfxPrivateKeySource</code></a> — A WebCrypto private key or raw PKCS#8 DER bytes for a PFX key bag.</li><li><span id="type-parsedpkcs7signeddata"></span><a href="/v0.1.1/api/type/ParsedPkcs7SignedData"><code>ParsedPkcs7SignedData</code></a> — Decoded PKCS#7 SignedData content, including certificates and signer info.</li><li><span id="type-parsedpkcs7signerinfo"></span><a href="/v0.1.1/api/type/ParsedPkcs7SignerInfo"><code>ParsedPkcs7SignerInfo</code></a> — A single SignerInfo decoded from a PKCS#7 SignedData structure.</li><li><span id="type-parsepkcs7certbagresult"></span><a href="/v0.1.1/api/type/ParsePkcs7CertBagResult"><code>ParsePkcs7CertBagResult</code></a> — Success-or-failure result from <a href="/v0.1.1/api/fn/parsePkcs7CertBagDer"><code>parsePkcs7CertBagDer</code></a> / <a href="/v0.1.1/api/fn/parsePkcs7CertBagPem"><code>parsePkcs7CertBagPem</code></a>.</li><li><span id="type-parsepkcs7errorcode"></span><a href="/v0.1.1/api/type/ParsePkcs7ErrorCode"><code>ParsePkcs7ErrorCode</code></a> — Error codes for PKCS#7 parse failures.</li><li><span id="type-parsepkcs7failure"></span><a href="/v0.1.1/api/type/ParsePkcs7Failure"><code>ParsePkcs7Failure</code></a> — Error payload for a failed PKCS#7 parse.</li><li><span id="type-parsepkcs7signeddataresult"></span><a href="/v0.1.1/api/type/ParsePkcs7SignedDataResult"><code>ParsePkcs7SignedDataResult</code></a> — Success-or-failure result from <a href="/v0.1.1/api/fn/parsePkcs7SignedDataDer"><code>parsePkcs7SignedDataDer</code></a> / <a href="/v0.1.1/api/fn/parsePkcs7SignedDataPem"><code>parsePkcs7SignedDataPem</code></a>.</li><li><span id="type-pkcs7certbag"></span><a href="/v0.1.1/api/type/Pkcs7CertBag"><code>Pkcs7CertBag</code></a> — DER, PEM, and base64 encodings of a PKCS#7 certificate bag.</li><li><span id="type-pkcs7certificatesource"></span><a href="/v0.1.1/api/type/Pkcs7CertificateSource"><code>Pkcs7CertificateSource</code></a> — PEM text (may contain multiple CERTIFICATE blocks) or raw DER bytes.</li><li><span id="type-verifypkcs7signeddatafailure"></span><a href="/v0.1.1/api/type/VerifyPkcs7SignedDataFailure"><code>VerifyPkcs7SignedDataFailure</code></a> — Error payload for a failed <a href="/v0.1.1/api/fn/verifyPkcs7SignedData"><code>verifyPkcs7SignedData</code></a> call.</li><li><span id="type-verifypkcs7signeddataresult"></span><a href="/v0.1.1/api/type/VerifyPkcs7SignedDataResult"><code>VerifyPkcs7SignedDataResult</code></a> — Success-or-failure result from <a href="/v0.1.1/api/fn/verifyPkcs7SignedData"><code>verifyPkcs7SignedData</code></a>.</li><li><span id="type-parsedpkcs12macdata"></span><a href="/v0.1.1/api/type/ParsedPkcs12MacData"><code>ParsedPkcs12MacData</code></a> — Decoded PKCS#12 MacData block returned by <a href="/v0.1.1/api/fn/parsePkcs12MacData"><code>parsePkcs12MacData</code></a>.</li><li><span id="type-pkcs12macoptions"></span><a href="/v0.1.1/api/type/Pkcs12MacOptions"><code>Pkcs12MacOptions</code></a> — Input for <a href="/v0.1.1/api/fn/createPkcs12MacData"><code>createPkcs12MacData</code></a>.</li></ul>`,7)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};